package run.ikaros.notes; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/private-notes") public class PrivateNotesController{private final PrivateNotesService service;public PrivateNotesController(PrivateNotesService s){service=s;}@PostMapping("/vaults")public Mono<VaultView> vault(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@Valid@RequestBody CreateVaultRequest r){return service.createVault(a,r);}@GetMapping("/vaults")public Flux<VaultView> vaults(@RequestHeader("X-Ikaros-Actor-Id")UUID a){return service.vaults(a);}@PostMapping("/vaults/{id}/actions/lock")public Mono<VaultView> lock(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.lock(a,id);}@PostMapping("/vaults/{id}/actions/unlock")public Mono<VaultView> unlock(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.unlock(a,id);}@PostMapping("/vaults/{vaultId}/notebooks")public Mono<NotebookView> notebook(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@Valid@RequestBody CreateNotebookRequest r){return service.createNotebook(a,vaultId,r);}@GetMapping("/vaults/{vaultId}/notebooks")public Flux<NotebookView> notebooks(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.notebooks(a,vaultId);}@PostMapping("/vaults/{vaultId}/notes")public Mono<NoteView> note(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@Valid@RequestBody UpsertNoteRequest r){return service.createNote(a,vaultId,r);}@GetMapping("/vaults/{vaultId}/notes")public Flux<NoteView> notes(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.notes(a,vaultId);}@PutMapping("/notes/{id}")public Mono<NoteView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id,@Valid@RequestBody UpsertNoteRequest r){return service.updateNote(a,id,r);}@DeleteMapping("/notes/{id}")public Mono<NoteView> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.deleteNote(a,id);}}
